import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>BMP وJPG صيغتان قديمتان من عصر ويندوز، لكنهما مختلفتان تمامًا. لقطة BMP تزن 6 ميغابايت، بينما نفس الصورة بصيغة JPG تزن 500 كيلوبايت، وتبدوان متطابقتين على الشاشة.</p>\n<p>الفرق هو الضغط. BMP لا يضغط تقريبًا، بينما صُمم JPG ليضغط بقوة، وهذا القرار التصميمي الواحد يفسر فجوة الحجم كلها.</p>\n<p>تشرح هذه المقارنة لماذا تكون ملفات BMP كبيرة جدًا، وكم يوفر JPG، ومتى ما زال لكل صيغة دور.</p>\n<h2 id=\"bmp-at-a-glance\">BMP في لمحة</h2>\n<p>BMP هي صيغة الصور الأصلية في ويندوز من التسعينيات. تحفظ كل بكسل بدقة، مع ضغط قليل أو معدوم، ما يجعلها بسيطة وسريعة القراءة.</p>\n<p>صُممت الصيغة عندما كانت المعالجات بطيئة. حفظ البكسلات الخام يعني أن الحاسوب يستطيع عرضها فورًا دون إنفاق وقت في فك الضغط. وما زالت تنتجها برامج ويندوز القديمة والماسحات الضوئية وبعض الكاميرات الرقمية.</p>\n<h2 id=\"jpg-at-a-glance\">JPG في لمحة</h2>\n<p>JPG صيغة فاقدة من عام 1992، صُممت للصور الفوتوغرافية. تتخلص من التفاصيل لتصغير الملفات، وتؤدي هذا العمل جيدًا بما يكفي لتبقى ثلاثة عقود.</p>\n<p>كل الأجهزة والمتصفحات والطابعات ونماذج الرفع على الكوكب تستطيع فتح JPG. ولا يوجد نظام شائع يرفضه. ويدعم JPG لون 8 بت فقط ولا شفافية فيه: إنه مستطيل مسطح من البكسلات.</p>\n<h2 id=\"why-bmp-is-large\">لماذا تكون ملفات BMP كبيرة جدًا</h2>\n<p>ملف BMP يحفظ كل بكسل على حدة. لقطة 1920 في 1080 بلون 24 بت فيها أكثر من مليوني بكسل، وكل بكسل يحتاج ثلاثة بايتات، فيصبح المجموع أكثر من 6 ميغابايت.</p>\n<p>لا ذكاء في التخزين. الخلفية البيضاء التي يحفظها JPG في بايتات قليلة تحتاج آلاف البايتات في BMP، لأن كل بكسل أبيض يُكتب كاملًا. وبعض ملفات BMP تستخدم ضغط طول السلسلة، لكن معظمها يُحفظ خامًا دون أي ضغط.</p>\n<h2 id=\"how-much-jpg-saves\">كم يوفر JPG فعلًا</h2>\n<p>لقطة BMP 6 ميغابايت تتحول إلى JPG 500 كيلوبايت بجودة 85 بالمئة. هذا توفير 92 بالمئة، مع بقاء الصورة نظيفة.</p>\n<p>مسح BMP 10 ميغابايت يتحول إلى JPG 300 كيلوبايت بالإعداد نفسه، أي توفير 97 بالمئة، لأن المسحات ورق أبيض في الغالب مع نص داكن. وصورة BMP 20 ميغابايت تتحول إلى JPG 1.5 ميغابايت بجودة 85 بالمئة.</p>\n<h2 id=\"quality-compared\">جودة الصورة: تعادل بإعدادات معقولة</h2>\n<p>بجودة 85 إلى 90 بالمئة، يبدو JPG مطابقًا لـBMP الذي خرج منه في أحجام العرض العادية. التفاصيل المتخلص منها غير مرئية للعين البشرية.</p>\n<p>وبجودة 100 بالمئة، يكون JPG شبه مطابق لـBMP حتى على مستوى البكسل، ويبقى الملف أصغر بكثير. أما بجودة منخفضة فيظهر الفرق: JPG 50 بالمئة يظهر آثار كتل ونصًا ناعمًا، بينما BMP يبقى مثاليًا لأنه لا يتخلص من شيء أبدًا.</p>\n<h2 id=\"colour-depth-compared\">عمق اللون مقارنة</h2>\n<p>BMP 24 بت وJPG يستخدمان لون 24 بت، مع ملايين الألوان المتاحة. التحويل بينهما يحافظ على نطاق اللون بدقة.</p>\n<p>BMP 8 بت يستخدم لوحة 256 لونًا، وتحويله إلى JPG يوسّع اللوحة إلى ألوان RGB عادية وتبدو الصورة نفسها. أما BMP 1 بت فيحفظ أبيض وأسود فقط، وتحويله إلى JPG ينتج صورة أبيض وأسود بنفس البكسلات بجزء من الحجم.</p>\n<h2 id=\"transparency-compared\">الشفافية: لا صيغة تدعمها</h2>\n<p>ملفات BMP القياسية لا تدعم الشفافية. كل بكسل له لون صلب ولا توجد قناة ألفا للمناطق الشفافة.</p>\n<p>JPG لا يدعم الشفافية أيضًا. إنه مستطيل مسطح من البكسلات دون طريقة لحفظ أجزاء شفافة. وتحويل BMP إلى JPG لا يفقد شيئًا في الشفافية، لأن الصورة كانت معتمة قبلًا وتبقى معتمة بعدًا. وإذا احتجت شفافية، استخدم PNG أو WebP.</p>\n<h2 id=\"compatibility-compared\">التوافق: JPG يفوز تمامًا</h2>\n<p>JPG يُفتح في كل الأجهزة وأنظمة التشغيل والمتصفحات ونماذج الرفع. لا يوجد نظام شائع يرفض JPG.</p>\n<p>أما BMP فيُفتح في ويندوز أصليًا، لكن الدعم في أماكن أخرى متفاوت. أجهزة ماك والهواتف ومتصفحات الويب قد تعرض BMP، لكن كثيرًا من الأدوات والنماذج ترفضه. وعملاء البريد يحجبون مرفقات BMP غالبًا لأنها كبيرة جدًا، ومواقع الويب نادرًا ما تقبل رفع BMP.</p>\n<h2 id=\"when-to-use-bmp\">متى ما زال BMP منطقيًا</h2>\n<p>BMP منطقي داخل برامج ويندوز القديمة التي تنتجه أصليًا. التطبيق القديم قد يحفظ BMP فقط، والتحويل خطوة منفصلة لا جزء من سير العمل.</p>\n<p>كما أن BMP منطقي كصيغة وسيطة أثناء التحرير، لأن بعض الأدوات القديمة تعمل مع BMP داخليًا. ولأرشيف الأصول في حالات نادرة، BMP دون فقدان نسخة مثالية، لكن PNG صيغة أرشيف أفضل لأنه دون فقدان أيضًا وأصغر بكثير.</p>\n<h2 id=\"when-to-use-jpg\">متى يفوز JPG بوضوح</h2>\n<p>استخدم JPG للمشاركة والإرسال بالبريد والرفع. الملفات الصغيرة تُرسل بسرعة وتُرفع دون تجاوز الحدود وتُفتح في كل مكان.</p>\n<p>واستخدم JPG لمواقع الويب. صورة BMP في صفحة ويب بطيئة وغالبًا غير متوافقة، بينما JPG يُحمَّل بسرعة ويُعرض في كل المتصفحات. واستخدم JPG لأرشفة المسحات واللقطات، ولأي صورة يجب أن تعمل خارج ويندوز.</p>\n<h2 id=\"converting-strategy\">استراتيجية لملفات BMP القديمة</h2>\n<p>حوّل ملفات BMP إلى JPG فور استلامها. التحويل يستغرق ثواني، والتوفير هائل، والنتيجة تعمل في كل مكان.</p>\n<p>احفظ ملفات BMP الأصلية في مجلد أرشيف إذا كانت مهمة، فهي الأصول ويمكنك تحويلها مجددًا إذا احتجت صيغة أخرى لاحقًا. واستخدم جودة 85 بالمئة افتراضيًا، فهي تبقي النص مقروءًا والصور نظيفة وتقلص الملفات 90 بالمئة أو أكثر. ولأرشيف كامل، حوّل دفعة واحدة باستخدام <a href=\"/ar/tahwil-bmp-ila-jpg/\">محول BMP إلى JPG</a>.</p>\n<h2 id=\"verdict\">الحكم: أي صيغة تفوز؟</h2>\n<p>JPG يفوز في الحجم والتوافق والعملية. إنه أصغر 90 بالمئة أو أكثر، ويُفتح في كل مكان، ويبدو مطابقًا بإعدادات جودة معقولة.</p>\n<p>أما BMP فيفوز فقط في البساطة والتخزين دون فقدان. إنه نسخة مثالية من البكسلات، وهذا مهم لأصول الأرشيف وللبرامج القديمة التي تنتجه. ولكل الاستخدامات الحقيقية تقريبًا، JPG هو الصيغة الصحيحة.</p>\n<h2 id=\"bmp-in-medical-imaging\">BMP في التصوير الطبي</h2>\n<p>برامج التصوير الطبي تحفظ المسحات أحيانًا كـBMP، لأن الصيغة بسيطة ودون فقدان. المسح الواحد قد يزن عشرات الميغابايت، ما يصعّب التخزين والمشاركة.</p>\n<p>حوّل المسحات إلى JPG بجودة 90 بالمئة للمشاركة. تبقى الصور حادة بما يكفي للمراجعة، بينما تتقلص الملفات بشكل كبير وتُرسل بسهولة. وللتشخيص، لا تعتمد أبدًا على نسخة فاقدة: المسح المضغوط قد يخفي تفاصيل أو يخترعها، فالأصل BMP أو PNG دون فقدان هو النسخة الآمنة الوحيدة لقرارات التشخيص.</p>\n<h2 id=\"bmp-in-industrial-software\">BMP في البرامج الصناعية</h2>\n<p>البرامج الصناعية، مثل أنظمة الرؤية الآلية ومراقبة الجودة، تحفظ الصور غالبًا كـBMP. الصيغة بسيطة وسريعة الكتابة وسهلة القراءة للبرامج.</p>\n<p>حوّل الصور إلى JPG قبل مشاركتها مع الزملاء. مرفق BMP 20 ميغابايت يتجاوز معظم حدود البريد، بينما نسخة JPG 500 كيلوبايت تُرسل فورًا. ولأرشيف مراقبة الجودة، احفظ ملفات BMP الأصلية، لأن الملفات دون فقدان هي الدليل.</p>\n<h2 id=\"storage-costs-bmp\">تكاليف تخزين BMP</h2>\n<p>ملفات BMP تكلف مالًا حقيقيًا في التخزين. مجلد فيه ألف لقطة 6 ميغابايت يحتاج 6 غيغابايت من القرص، بينما نفس المجلد كـJPG يحتاج 500 ميغابايت، أي فرق اثني عشر ضعفًا.</p>\n<p>التخزين السحابي يحاسب بالغيغابايت، فملف BMP يكلف اثني عشر ضعف ملف JPG. والنسخ الاحتياطية تكلف أيضًا: ملف BMP يستغرق اثني عشر ضعف الوقت في النسخ الاحتياطي ويملأ قرص النسخ أسرع باثني عشر ضعفًا. ولعمل لديه أرشيف صور كبير، التوفير كبير.</p>\n<h2 id=\"bmp-in-old-video-games\">BMP في ألعاب الفيديو القديمة</h2>\n<p>ألعاب الفيديو القديمة تحفظ القوام والرسوم كملفات BMP، لأن الصيغة كانت المعيار عندما كُتبت الألعاب. هذه الملفات كبيرة والأدوات الحديثة تفضل صيغًا أخرى.</p>\n<p>حوّل قوام اللعبة إلى PNG للتحرير. الصيغة دون فقدان تحافظ على البكسلات بدقة، وهذا مهم لفن البكسل حيث كل بكسل مقصود. ولمشاركة لقطات ألعاب قديمة، حوّل إلى JPG، فاللقطات تتقلص 90 بالمئة والمنتديات ووسائل التواصل تتعامل مع JPG أصليًا.</p>\n<h2 id=\"migrating-bmp-archive\">ترحيل أرشيف BMP</h2>\n<p>ترحيل أرشيف BMP مشروع لا مهمة. خطط له دفعة دفعة، مجلدًا واحدًا في كل مرة، متحققًا من كل دفعة قبل الانتقال إلى التالية.</p>\n<p>ابدأ بالمجلد الأقل أهمية، لأن الخطأ هناك يكلف قليلًا. وحوّل كل دفعة بجودة 85 بالمئة ثم تحقق من عينة من الملفات. واحفظ ملفات BMP الأصلية حتى يُتحقق من الترحيل كاملًا، لأن حذفها مبكرًا يخاطر بفقدان ملفات لا يمكن إعادة إنشائها.</p>\n<p>هل تحتاج إلى التحويل الآن؟ افتح <a href=\"/ar/tahwil-bmp-ila-jpg/\">أداة BMP إلى JPG</a> وأسقط ملفاتك. وللخطوات، اقرأ <a href=\"/ar/blog/kayfiyya-tahwil-bmp-ila-jpg/\">كيف تحوّل BMP إلى JPG</a>، وللسياق العام راجع <a href=\"/ar/blog/dalil-tahwil-bmp-ila-jpg/\">BMP إلى JPG: الدليل الكامل</a>. وإذا احتجت تحويل صيغ كثيرة مختلفة دفعة واحدة، فـ<a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> يتعامل مع دفعات مختلطة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"لماذا تكون ملفات BMP ضخمة جدًا مقارنة بـJPG؟","answer":"BMP يحفظ كل بكسل بدقة ودون ضغط تقريبًا، فلقطة 1920 في 1080 تحتاج أكثر من 6 ميغابايت للبكسلات وحدها. JPG يتخلص من تفاصيل لا تلاحظها العين ويضغط نفس الصورة إلى 500 كيلوبايت."},{"question":"هل تحويل BMP إلى JPG يفقد جودة الصورة؟","answer":"قليل جدًا بإعدادات معقولة. بجودة 85 إلى 90 بالمئة، يبدو JPG مطابقًا لـBMP في أحجام العرض العادية. التفاصيل المتخلص منها غير مرئية للعين البشرية. فقط بإعدادات جودة منخفضة، دون 70 بالمئة، تظهر الآثار."},{"question":"هل BMP أفضل جودة من JPG للأرشفة؟","answer":"BMP دون فقدان، فهو نسخة مثالية، لكن PNG صيغة أرشيف أفضل، لأنه دون فقدان أيضًا وأصغر بكثير. JPG فاقد، فليس مثاليًا للأصول. احفظ الأصول كـBMP أو PNG، واستخدم JPG للمشاركة."},{"question":"هل يمكنني تحويل BMP إلى JPG دون فقدان الألوان؟","answer":"نعم عمليًا، فـBMP 24 بت وJPG يستخدمان لون 24 بت، فالتحويل يحافظ على نطاق اللون. اللوحات غير المعتادة جدًا في ملفات 8 بت القديمة قد تتغير قليلًا، لكن الفرق نادرًا ما يكون مرئيًا."},{"question":"لماذا ما زالت بعض البرامج تحفظ الصور كـBMP؟","answer":"برامج ويندوز القديمة بُنيت حول BMP، لأن البكسلات الخام كانت سريعة القراءة والكتابة على المعالجات البطيئة. الصيغة تستمر في التطبيقات القديمة والماسحات وبعض الكاميرات التي لم تُحدَّث."},{"question":"هل يجب أن أحوّل كل ملفات BMP القديمة إلى JPG؟","answer":"نعم للملفات التي تستخدمها أو تشاركها أو ترفعها، لأن توفير 90 بالمئة والتوافق الشامل يستحقان ذلك. واحفظ ملفات BMP الأصلية في مجلد أرشيف إذا كانت مهمة، لأن JPG لا يمكن أن يعود BMP أبدًا."}];
